import { createTheme } from "@mui/material";

export const ZB_COLORS = {
  navy: "#050d1a",
  navyMid: "#0d1f3c",
  blue: "#1a237e",
  gold: "#ffd600",
  goldDim: "rgba(255,214,0,0.12)",
  white: "#ffffff",
  textPrimary: "#e8edf4",
  textMuted: "rgba(232,237,244,0.55)",
  border: "rgba(255,255,255,0.08)",
  cardBg: "rgba(255,255,255,0.04)",
  cardHover: "rgba(255,255,255,0.07)",
};

const theme = createTheme({
  palette: {
    mode: "dark",
    primary: { main: ZB_COLORS.gold },
    secondary: { main: ZB_COLORS.blue },
    background: { default: ZB_COLORS.navy, paper: ZB_COLORS.navyMid },
    text: { primary: ZB_COLORS.textPrimary, secondary: ZB_COLORS.textMuted },
  },
  typography: {
    fontFamily: "'Sora', 'DM Sans', sans-serif",
    h1: { fontWeight: 700, letterSpacing: "-0.03em" },
    h2: { fontWeight: 700, letterSpacing: "-0.02em" },
    h3: { fontWeight: 700, letterSpacing: "-0.02em" },
    h4: { fontWeight: 700, letterSpacing: "-0.02em" },
    h5: { fontWeight: 600 },
    h6: { fontWeight: 600 },
    body1: { fontFamily: "'DM Sans', sans-serif", lineHeight: 1.7 },
    body2: { fontFamily: "'DM Sans', sans-serif", lineHeight: 1.6 },
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 8,
          textTransform: "none",
          fontFamily: "'DM Sans', sans-serif",
          fontWeight: 600,
        },
        containedPrimary: {
          background: ZB_COLORS.gold,
          color: "#0a0a0a",
          "&:hover": { background: "#e6c200", boxShadow: "none" },
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          backgroundImage: "none",
          backgroundColor: ZB_COLORS.navyMid,
          border: `0.5px solid ${ZB_COLORS.border}`,
        },
      },
    },
    MuiTextField: {
      styleOverrides: {
        root: {
          "& .MuiOutlinedInput-root": {
            fontFamily: "'DM Sans', sans-serif",
            "& fieldset": { borderColor: ZB_COLORS.border },
            "&:hover fieldset": { borderColor: "rgba(255,255,255,0.25)" },
            "&.Mui-focused fieldset": { borderColor: ZB_COLORS.gold },
          },
          "& .MuiInputLabel-root": { fontFamily: "'DM Sans', sans-serif" },
        },
      },
    },
    MuiChip: {
      styleOverrides: {
        root: { fontFamily: "'DM Sans', sans-serif", fontSize: "0.75rem" },
      },
    },
    MuiCssBaseline: {
      styleOverrides: `
        @import url('https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700&family=DM+Sans:wght@400;500;600&display=swap');
        * { box-sizing: border-box; }
        body { background: ${ZB_COLORS.navy}; margin: 0; }
        ::-webkit-scrollbar { width: 6px; }
        ::-webkit-scrollbar-track { background: ${ZB_COLORS.navy}; }
        ::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.15); border-radius: 3px; }
      `,
    },
  },
});

export default theme;
